// ---- player.c ----
#include "player.h"

static int clamp_health(int h) {
    return h > 100 ? 100 : h;
}

void player_heal(Player* p, int amount) {
    p->health = clamp_health(p->health + amount);
}

// ---- main.c ----
#include <stdio.h>
#include "player.h"

int main(void) {
    Player hero = {90};
    player_heal(&hero, 25);
    printf("health %d, alive %d\n", hero.health, player_alive(&hero));
    return 0;
}

